#include <zephyr/storage/flash_map.h>
#include <zephyr/drivers/flash.h> 
#include <zephyr/device.h>
#include <zephyr/init.h>
#include <string.h>
#include <zephyr/sys/util.h>

#define LOG_LEVEL CONFIG_FLASH_MAP_LOG_LEVEL
#include <zephyr/logging/log.h>
LOG_MODULE_REGISTER(flash_map);

/*
 * Statically defined flash map. The linker script places this in a special
 * section.
 */
extern const struct flash_area flash_map[];
extern const int flash_map_entries;

static bool flash_area_is_open(const struct flash_area *fa)
{
	return fa->fa_dev != NULL;
}

int flash_area_open(uint8_t id, const struct flash_area **fa_p)
{
	const struct flash_area *fa;

	if (fa_p == NULL) {
		return -EINVAL;
	}

	for (fa = flash_map; fa < flash_map + flash_map_entries; fa++) {
		if (id == fa->fa_id) {
			*fa_p = fa;
			if (!device_is_ready(fa->fa_dev)) {
				LOG_ERR("Flash device %s not ready", fa->fa_dev->name);
				return -ENODEV;
			}
			return 0;
		}
	}
	return -ENOENT;
}

void flash_area_close(const struct flash_area *fa)
{
	/* This backend requires no close. */
}

int flash_area_read(const struct flash_area *fa, off_t off, void *dst,
		    size_t len)
{
	if (!flash_area_is_open(fa)) {
		return -EBADF;
	}

	if (off < 0) {
		return -EINVAL;
	}

	if (len == 0) {
		return off > fa->fa_size ? -EINVAL : 0;
	}

	if (off > fa->fa_size || len > fa->fa_size - off) {
		return -EINVAL;
	}

	return flash_read(fa->fa_dev, fa->fa_off + off, dst, len);
}

int flash_area_write(const struct flash_area *fa, off_t off, const void *src,
		     size_t len)
{
	if (!flash_area_is_open(fa)) {
		return -EBADF;
	}

	if (off < 0) {
		return -EINVAL;
	}

	if (len == 0) {
		return off > fa->fa_size ? -EINVAL : 0;
	}

	if (off > fa->fa_size || len > fa->fa_size - off) {
		return -EINVAL;
	}

	return flash_write(fa->fa_dev, fa->fa_off + off, src, len);
}

int flash_area_erase(const struct flash_area *fa, off_t off, size_t len)
{
	if (!flash_area_is_open(fa)) {
		return -EBADF;
	}

	if (off < 0) {
		return -EINVAL;
	}

	if (len == 0) {
		return off > fa->fa_size ? -EINVAL : 0;
	}

	if (off > fa->fa_size || len > fa->fa_size - off) {
		return -EINVAL;
	}

	return flash_erase(fa->fa_dev, fa->fa_off + off, len);
}

uint8_t flash_area_get_id(const struct flash_area *fa)
{
	return fa->fa_id;
}

const struct device *flash_area_get_device(const struct flash_area *fa)
{
	return fa->fa_dev;
}
